def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    my = [h[0] for h in history]
    op = [h[1] for h in history]
    opp_def = op.count('D')
    my_def = my.count('D')
    last_my_D = -1
    for i in range(n - 1, -1, -1):
        if my[i] == 'D':
            last_my_D = i
            break
    non_ret = 0
    ret = 0
    for i in range(1, n):
        if my[i - 1] == 'D':
            if op[i] == 'C':
                non_ret += 1
            else:
                ret += 1
    last_me = my[-1]
    last_op = op[-1]
    opp_coop_rate = (n - opp_def) / n
    if opp_def == 0:
        if my_def == 0:
            if n >= 5:
                return 'D'
            return 'C'
        else:
            return 'D'
    if opp_def <= 2 or opp_coop_rate > 0.8:
        if last_me == 'D' and last_op == 'D':
            if n >= 2:
                prev_me, prev_op = history[-2]
                if prev_me == 'D' and prev_op == 'C' and non_ret > 0:
                    return 'C'
        if last_me == 'C' and last_op == 'D':
            if n >= 2:
                prev_me, prev_op = history[-2]
                if prev_me == 'D' and prev_op == 'D' and non_ret > 0:
                    return 'C'
    if last_me == 'D' and last_op == 'D':
        return 'D'
    if last_me == 'C' and last_op == 'D':
        if opp_coop_rate > 0.7 and n > 10 and rng.random() < 0.1:
            return 'C'
        return 'D'
    if last_me == 'D' and last_op == 'C':
        if ret == 0:
            if non_ret >= 2:
                return 'D'
            else:
                return 'C'
        else:
            return 'C'
    if last_me == 'C' and last_op == 'C':
        return 'C'
    return 'C'
